parameters.jsCode:
// Parse Gemini response and extract queries
const response = $input.item.json;
const text = response.candidates[0].content.parts[0].text;

// Extract JSON array from text
const jsonMatch = text.match(/\[.*\]/s);
if (!jsonMatch) {
  throw new Error('Failed to extract queries from Gemini response');
}

const queries = JSON.parse(jsonMatch[0]);

// Return array of query objects
return queries.map((query, index) => ({
  json: {
    query: query,
    queryIndex: index + 1,
    patternName: $input.item.json.patternName
  }
}));

// Filter and rank search results
const items = $input.all();
const allResults = [];

// Extract all organic results from all queries
for (const item of items) {
  const results = item.json.organic_results || [];

  for (const result of results) {
    const url = result.link;
    const domain = new URL(url).hostname;

    // Priority scoring
    let score = 0;

    // Official domains (high priority)
    if (domain.includes('github.com') || 
        domain.includes('docs.') || 
        domain.includes('.dev') ||
        domain.includes('npmjs.com') ||
        domain.includes('reactjs.org') ||
        domain.includes('redux.js.org')) {
      score += 10;
    }

    // Trusted tech blogs (medium priority)
    if (domain.includes('medium.com') ||
        domain.includes('dev.to') ||
        domain.includes('css-tricks.com') ||
        domain.includes('smashingmagazine.com') ||
        domain.includes('freecodecamp.org')) {
      score += 5;
    }

    // Avoid certain domains
    if (domain.includes('stackoverflow.com') ||
        domain.includes('reddit.com') ||
        domain.includes('quora.com')) {
      score -= 5;
    }

    allResults.push({
      url: url,
      title: result.title,
      snippet: result.snippet,
      domain: domain,
      score: score
    });
  }
}

// Remove duplicates by URL
const uniqueResults = [];
const seenUrls = new Set();

for (const result of allResults) {
  if (!seenUrls.has(result.url)) {
    seenUrls.add(result.url);
    uniqueResults.push(result);
  }
}

// Sort by score and take top 5
const topResults = uniqueResults
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

// Return as separate items for next loop
return topResults.map(result => ({
  json: {
    url: result.url,
    title: result.title,
    snippet: result.snippet,
    domain: result.domain,
    patternName: items[0].json.patternName
  }
}));

// Parse HTML and extract main content using cheerio
const cheerio = require('cheerio');
const html = $input.item.json.data || $input.item.json.body || '';

if (!html) {
  return [{
    json: {
      url: $input.item.json.url,
      title: $input.item.json.title,
      content: $input.item.json.snippet || '',
      contentLength: 0,
      patternName: $input.item.json.patternName
    }
  }];
}

const $ = cheerio.load(html);

// Remove unwanted elements
$('script, style, nav, header, footer, iframe, noscript, .ad, .advertisement, .sidebar').remove();

// Try to find main content area
let content = '';

// Priority selectors for main content
const selectors = [
  'article',
  'main',
  '.content',
  '.post-content',
  '.article-content',
  '.entry-content',
  '#content',
  '.markdown-body', // GitHub
  '[role="main"]'
];

for (const selector of selectors) {
  const element = $(selector).first();
  if (element.length > 0) {
    content = element.text();
    break;
  }
}

// Fallback to body if no main content found
if (!content) {
  content = $('body').text();
}

// Clean up whitespace
content = content
  .replace(/\s+/g, ' ')
  .trim()
  .substring(0, 15000); // Limit to 15k chars per page

return [{
  json: {
    url: $input.item.json.url,
    title: $input.item.json.title,
    content: content,
    contentLength: content.length,
    patternName: $input.item.json.patternName
  }
}];

