// Parse Gemini responses and format for Notion
const contentResponse = $input.first().json;
const codeResponse = $input.last().json;

// Extract text from Gemini responses
const analysisText = contentResponse.candidates[0].content.parts[0].text;
const codeText = codeResponse.candidates[0].content.parts[0].text;

// Extract code block from markdown
let cleanCode = codeText;
const codeMatch = codeText.match(/```(?:typescript|tsx|ts)?\n([\s\S]*?)```/);
if (codeMatch) {
  cleanCode = codeMatch[1].trim();
}

// Parse markdown sections
const sections = {};
const sectionRegex = /# (.+?)\n([\s\S]*?)(?=\n# |$)/g;
let match;

while ((match = sectionRegex.exec(analysisText)) !== null) {
  const heading = match[1].trim();
  const content = match[2].trim();
  sections[heading] = content;
}

// Get pattern name and sources
const patternName = $input.first().json[0]?.patternName || 'Design Pattern';
const sources = $input.first().json.map(item => ({
  url: item.url,
  title: item.title
})).filter(s => s.url);

return [{
  json: {
    patternName: patternName,
    overview: sections['Overview'] || '',
    keyConcepts: sections['Key Concepts'] || '',
    advantages: sections['Advantages'] || '',
    disadvantages: sections['Disadvantages'] || '',
    useCases: sections['Use Cases'] || '',
    setupGuide: sections['Setup Guide'] || '',
    codeExample: cleanCode,
    sources: sources,
    createdAt: new Date().toISOString()
  }
}];
